head.script:
scwin.trigger1_onclick = function(e) {
    var options = {};
    options.fileName = "test1.cell";
    gridView1.advancedExcelDownload(options);
};
scwin.trigger2_onclick = function(e) {
    dataList1.removeAll();
};
scwin.trigger3_onclick = function(e) {
    var options = {
        type: "1",
        sheetNo: 0,
        startRowIndex: 1,
        startColumnIndex: 0,
        endColumnIndex: 2
    };
    gridView1.advancedExcelUpload(options);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. name2 의 Property 탭 또는 Source 탭 에서 inputType 과 viewType 을 확인한다.
    //1. Check the inputType and viewType in the Property tab or the Source tab of name2.
    //Verify step 1. inputType="autoComplete" / viewType="icon"
    //1. inputType = "autoComplete" / viewType = "icon"
    //Test step 2. 브라우저에서 name1 과 name2 컬럼을 확인한다.
    //2. Check the name1 and name2 columns in your browser.
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 2. inputType 이 Select 인 name1 처럼 name2 도 우측에 콤보 아이콘이 표시된다.
    //2. As with name1 with inputType of Select, name2 also has a combo icon on the right.
    WebSquare.wUnit.addCommand("assert", "document.getElementsByClassName('gridBodyDefault gridBodyDefault_data '+$p.id+'gridView1_columnstyle_1_ gridBodyDefault_autoComplete').length == 3", "true");
    WebSquare.wUnit.addCommand("assert", "document.getElementsByClassName('gridBodyDefault gridBodyDefault_data '+$p.id+'gridView1_columnstyle_0_ gridBodyDefault_select').length == 3", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.jsonData = [{
        "col1": "a1",
        "col2": "a2",
        "col3": "a3"
    }, {
        "col1": "b1",
        "col2": "b2",
        "col3": "b3"
    }, {
        "col1": "c1",
        "col2": "c2",
        "col3": "c3"
    }];
    dataList1.setJSON(jsonData);
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 09-Mar-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
